final class TapOpenTests: XCTestCase {
    func testTapOpenOnAlert() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let sbButton = springboard.alerts.buttons["Open"]
        if sbButton.waitForExistence(timeout: 10) {
            sbButton.tap()
            Thread.sleep(forTimeInterval: 2)
            return
        }
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        let bsButton = bluesky.alerts.buttons["Open"]
        if bsButton.waitForExistence(timeout: 5) {
            bsButton.tap()
        }
    }
}

